// span is one range of a list, from lo to hi inclusive, numbered from one.
type span struct{ lo, hi int }

// list is a parsed list: a field or byte is selected when any span holds
// it.
type list []span

func (l list) has(n int) bool {
	for _, s := range l {
		if n >= s.lo && n <= s.hi {
			return true
		}
	}
	return false
}

// words are the messages a list's errors use, which differ between a list
// of fields and one of bytes or characters, as in GNU.
type words struct {
	zero, tooLarge, invalid, badRange string
}

var (
	fieldWords = words{
		zero:     "fields are numbered from 1",
		tooLarge: "field number '%s' is too large",
		invalid:  "invalid field value '%s'",
		badRange: "invalid field range",
	}
	positionWords = words{
		zero:     "byte/character positions are numbered from 1",
		tooLarge: "byte/character offset '%s' is too large",
		invalid:  "invalid byte/character position '%s'",
		badRange: "invalid byte or character range",
	}
)

func blank(c byte) bool { return c == ' ' || c == '\t' }

// parseList reads a list as GNU's set_fields does: ranges N, N-M, N- and
// -M, numbered from one and separated by commas or blanks.
func parseList(s string, w words) (list, error) {
