}

// singleQuote writes name in single quotes, starting inside a $'...'
// escape or not, and reports whether it ended inside one.
func singleQuote(name string, inEscape bool) (string, bool) {
	var b strings.Builder
	b.WriteByte('\'')
	for i := 0; i < len(name); i++ {
		c := name[i]
		switch {
		case c == '\'':
			b.WriteString(`'\''`)
			inEscape = false
		case c < 0x20 || c >= 0x7f:
			if !inEscape {
				b.WriteString(`'$'`)
				inEscape = true
			}
			b.WriteString(escape(c))
		default:
			if inEscape {
				b.WriteString(`''`)
				inEscape = false
			}
			b.WriteByte(c)
		}
	}
	b.WriteByte('\'')
	return b.String(), inEscape
}

// QuoteAlways quotes s as GNU's quote does in the C locale: always in
// single quotes, with backslashes and single quotes escaped by a
// backslash and control and non-ASCII bytes written as C escapes.
func QuoteAlways(s string) string {
	var b strings.Builder
	b.WriteByte('\'')
	for i := 0; i < len(s); i++ {
		switch c := s[i]; {
		case c == '\\' || c == '\'':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c < 0x20 || c >= 0x7f:
			b.WriteString(escape(c))
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('\'')
	return b.String()
}

// escape writes a control or non-ASCII byte as C does: by its letter when
// it has one, else in three octal digits.
func escape(c byte) string {
	if i := strings.IndexByte("\a\b\f\n\r\t\v", c); i >= 0 {
		return `\` + string("abfnrtv"[i])
	}
	return fmt.Sprintf(`\%03o`, c)
}

