42	}
43	
44	// noTab is the field separator when -t is not given: fields are then
45	// separated by the empty string between a non-blank and a blank, so each
46	// field but the first starts with the blanks that precede it.
47	const noTab = -1
48	
49	// unbounded stands for a field or character count too large to reach.
50	const unbounded = math.MaxInt
51	
52	// key is one sort key, as -k gives it or as the global options make one of
53	// the whole line. Fields and characters count from zero here. A key with
54	// end false runs to the end of the line; an echar of zero ends the key at
55	// the end of field eword.
56	type key struct {
57		sword, schar int
58		eword, echar int
59		end          bool
60		// skipStart and skipEnd skip blanks before counting the start and
61		// end characters, as b does in POS1 and POS2.
62		skipStart, skipEnd bool
63		numeric, reverse   bool
64		// fold compares lowercase ASCII letters as uppercase, as f does.
65		fold bool
66		// human compares sizes such as 2K and 1M, as h does.
67		human bool
68	}
69	
70	// plain reports whether the key gives no ordering options of its own, in
71	// which case it takes the global ones, as GNU's keys do.
72	func (k key) plain() bool {
73		return !k.skipStart && !k.skipEnd && !k.numeric && !k.reverse && !k.fold && !k.human
74	}
75	
76	func blank(c byte) bool { return c == ' ' || c == '\t' }
77	
78	// field returns the part of line the key covers, found as GNU's begfield
79	// and limfield find it.
80	func (k key) field(line []byte, tab int) []byte {
81		lim := len(line)
82		if k.end {
83			lim = k.limit(line, tab)
84		}
85		beg := k.begin(line, tab)
86		if beg >= lim {
87			return nil
88		}
89		return line[beg:lim]
90	}
91	
92	func (k key) begin(line []byte, tab int) int {
93		p, n := 0, len(line)
94		for w := k.sword; p < n && w > 0; w-- {
95			p = skipField(line, p, tab)
96			if tab != noTab && p < n {
97				p++
98			}
99		}
100		if k.skipStart {
101			for p < n && blank(line[p]) {
102				p++
103			}
104		}
105		return advance(p, k.schar, n)
106	}
107	
108	func (k key) limit(line []byte, tab int) int {
109		p, n := 0, len(line)
110		w := k.eword
111		if k.echar == 0 && w < unbounded {
112			w++ // the whole of the end field
113		}
114		for ; p < n && w > 0; w-- {
115			p = skipField(line, p, tab)
116			if tab != noTab && p < n && (w > 1 || k.echar != 0) {
117				p++
118			}
119		}
120		if k.echar != 0 {
121			if k.skipEnd {
122				for p < n && blank(line[p]) {
123					p++
124				}
125			}
126			p = advance(p, k.echar, n)
127		}
128		return p
129	}
130	
131	// skipField moves from p past one field, up to its separator: with a tab,
132	// to the next tab; without, past leading blanks and then the non-blanks.
133	func skipField(line []byte, p, tab int) int {
134		n := len(line)
135		if tab != noTab {
136			for p < n && int(line[p]) != tab {
137				p++
138			}
139			return p
140		}
141		for p < n && blank(line[p]) {
142			p++
143		}
144		for p < n && !blank(line[p]) {
145			p++
146		}
147		return p
148	}
149	
150	func advance(p, by, n int) int {
151		if by >= n-p {
152			return n
153		}
154		return p + by
155	}
156	
157	// order is how lines compare: by their keys in turn, then, when every key
158	// ties, by their bytes, reversed by the global -r alone. With keys, -s and
159	// -u skip that last resort, so lines whose keys tie compare equal; without
160	// keys, the whole line is the key.
161	type order struct {
162		keys    []key
163		tab     int
164		reverse bool
165		// noLastResort is set by -s or -u.
166		noLastResort bool
167	}
168	
169	// unitOrder is the rank of a size's unit as -h reads it: 0 for none, then
170	// K (or k), M, G, T, P, E, Z, Y, R, Q from 1.
171	func unitOrder(c byte) int {
172		if c == 'k' {
173			c = 'K'
174		}
175		return strings.IndexByte("KMGTPEZYRQ", c) + 1
176	}
177	
178	// humanOrder finds the unit of s's leading number, as GNU's
179	// find_unit_order does: the byte after its digits and any fraction, when
180	// some digit is not zero; negated for a negative number. No unit, or a
181	// number all zeros, ranks 0. With fold, as with -f, the unit is read
182	// uppercased, so 5g is 5G.
183	func humanOrder(s []byte, fold bool) int {
184		i := 0
185		for i < len(s) && blank(s[i]) {
186			i++
187		}
188		neg := i < len(s) && s[i] == '-'
189		if neg {
190			i++
191		}
192		nonzero := false
193		digits := func() {
194			for ; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
195				nonzero = nonzero || s[i] != '0'
196			}
197		}
198		digits()
199		if i < len(s) && s[i] == '.' {
200			i++
201			digits()
202		}
203		if !nonzero || i >= len(s) {
204			return 0
205		}
206		u := s[i]
207		if fold && 'a' <= u && u <= 'z' {
208			u -= 'a' - 'A'
209		}
210		o := unitOrder(u)
211		if neg {
212			o = -o
213		}
214		return o
215	}
216	
217	// humancompare compares two sizes as -h does: by unit, then by number as
218	// -n compares them.
219	func humancompare(a, b []byte, fold bool) int {
220		if c := cmp.Compare(humanOrder(a, fold), humanOrder(b, fold)); c != 0 {
221			return c
222		}
223		return numcompare(a, b)
224	}
225	
226	// foldCompare compares a and b as bytes with lowercase ASCII letters made
227	// uppercase, as GNU's -f does in the C locale; so "_" sorts after letters.
228	func foldCompare(a, b []byte) int {
229		for i := 0; i < len(a) && i < len(b); i++ {
230			x, y := a[i], b[i]
231			if 'a' <= x && x <= 'z' {
232				x -= 'a' - 'A'
233			}
234			if 'a' <= y && y <= 'z' {
235				y -= 'a' - 'A'
236			}
237			if x != y {
238				return cmp.Compare(x, y)
239			}
240		}
241		return cmp.Compare(len(a), len(b))
242	}
243	
244	func (o order) compare(a, b []byte) int {
245		for _, k := range o.keys {
246			x, y := k.field(a, o.tab), k.field(b, o.tab)
247			var c int
248			if k.numeric {
249				c = numcompare(x, y)
250			} else if k.human {
251				c = humancompare(x, y, k.fold)
252			} else if k.fold {
253				c = foldCompare(x, y)
254			} else {
255				c = bytes.Compare(x, y)
256			}
257			if c != 0 {
258				if k.reverse {
259					c = -c
260				}
261				return c
262			}
263		}
264		if len(o.keys) > 0 && o.noLastResort {
265			return 0
266		}
267		c := bytes.Compare(a, b)
268		if o.reverse {
269			c = -c
270		}
271		return c
272	}
273	
274	// specError is a bad -k argument, in GNU's words.
275	func specError(msg, spec string) error {
276		return fmt.Errorf("%s: invalid field specification %s", msg, input.QuoteAlways(spec))
277	}
278	
279	// count reads a field or character count at the start of s, as GNU's
280	// parse_field_count does: optional white space and plus sign, then
281	// digits. A count too large to hold reads as unbounded.
282	func count(s, msg string) (int, string, error) {
283		i := 0
284		for i < len(s) && strings.IndexByte(" \t\n\v\f\r", s[i]) >= 0 {
285			i++
286		}
287		if i < len(s) && s[i] == '+' {
288			i++
289		}
290		start := i
291		n := 0
292		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
293			d := int(s[i] - '0')
294			if n > (unbounded-d)/10 {
295				n = unbounded
296			} else if n != unbounded {
297				n = n*10 + d
298			}
299			i++
300		}
301		if i == start {
302			return 0, "", fmt.Errorf("%s: invalid count at start of %s", msg, input.QuoteAlways(s))
303		}
304		return n, s[i:], nil
305	}
306	
307	// options reads the ordering letters after a position. b applies to the
308	// start or the end of the key, depending on which position it follows.
309	func options(s string, k *key, end bool) (string, error) {
310		for ; s != ""; s = s[1:] {
311			switch s[0] {
312			case 'b':
313				if end {
314					k.skipEnd = true
315				} else {
316					k.skipStart = true
317				}
318			case 'n':
319				k.numeric = true
320			case 'r':
321				k.reverse = true
322			case 'f':
323				k.fold = true
324			case 'h':
325				k.human = true
326			case 'd', 'g', 'i', 'M', 'R', 'V':
327				return "", fmt.Errorf("key option '%c' is not supported", s[0])
328			default:
329				return s, nil
330			}
331		}
332		return s, nil
333	}
334	
335	// parseKey reads a -k argument: POS1[,POS2], each position F[.C][OPTS].
336	func parseKey(spec string) (key, error) {
337		var k key
338		n, s, err := count(spec, "invalid number at field start")
339		if err != nil {
340			return k, err
341		}
342		if n == 0 {
343			return k, specError("field number is zero", spec)
344		}
345		k.sword = n - 1
346		if strings.HasPrefix(s, ".") {
347			if n, s, err = count(s[1:], "invalid number after '.'"); err != nil {
348				return k, err
349			}
350			if n == 0 {
351				return k, specError("character offset is zero", spec)
352			}
353			k.schar = n - 1
354		}
355		if s, err = options(s, &k, false); err != nil {
356			return k, err
357		}
358		if strings.HasPrefix(s, ",") {
359			k.end = true
360			if n, s, err = count(s[1:], "invalid number after ','"); err != nil {
361				return k, err
362			}
363			if n == 0 {
364				return k, specError("field number is zero", spec)
365			}
366			k.eword = n - 1
367			if strings.HasPrefix(s, ".") {
368				if k.echar, s, err = count(s[1:], "invalid number after '.'"); err != nil {
369					return k, err
370				}
371			}
372			if s, err = options(s, &k, true); err != nil {
373				return k, err
374			}
375		}
376		if s != "" {
377			return k, specError("stray character in field spec", spec)
378		}
379		return k, nil
380	}
381	
382	// parseTab reads a -t argument: one byte, or "\0" for the NUL byte.
383	func parseTab(s string) (int, error) {
384		switch {
385		case s == "":
386			return 0, errors.New("empty tab")
387		case s == `\0`:
388			return 0, nil
389		case len(s) > 1:
390			return 0, fmt.Errorf("multi-character tab %s", input.QuoteAlways(s))
391		}
392		return int(s[0]), nil
393	}
394	
395	// number is a line's leading number, as -n reads it: its sign, its
396	// integer digits without leading zeros and its fraction digits without
397	// trailing zeros.
398	type number struct {
399		neg      bool
400		whole    []byte
401		fraction []byte
402	}
403	
404	// parseNumber reads a line's leading number: blanks, an optional minus,
405	// digits, and an optional point with more digits. A line that does not
406	// start with one reads as zero, and so does negative zero.
407	func parseNumber(s []byte) number {
408		i := 0
409		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
410			i++
411		}
412		var n number
413		if i < len(s) && s[i] == '-' {
414			n.neg = true
415			i++
416		}
417		start := i
418		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
419			i++
420		}
421		n.whole = bytes.TrimLeft(s[start:i], "0")
422		if i < len(s) && s[i] == '.' {
423			i++
424			start = i
425			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
426				i++
427			}
428			n.fraction = bytes.TrimRight(s[start:i], "0")
429		}
430		if len(n.whole) == 0 && len(n.fraction) == 0 {
431			n.neg = false
432		}
433		return n
434	}
435	
436	// numcompare compares the leading numbers of two lines exactly, digit by
437	// digit, however long they are.
438	func numcompare(a, b []byte) int {
439		x, y := parseNumber(a), parseNumber(b)
440		if x.neg != y.neg {
441			if x.neg {
442				return -1
443			}
444			return 1
445		}
446		c := magnitude(x, y)
447		if x.neg {
448			c = -c
449		}
450		return c
451	}
452	
453	func magnitude(x, y number) int {
454		if len(x.whole) != len(y.whole) {
455			if len(x.whole) < len(y.whole) {
456				return -1
457			}
458			return 1
459		}
460		if c := bytes.Compare(x.whole, y.whole); c != 0 {
461			return c
462		}
463		return bytes.Compare(x.fraction, y.fraction)
464	}
465	
466	func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
467		given, names, err := opts.Parse(args, spec)
468		if err != nil {
469			fmt.Fprintf(stderr, "sort: %v\nTry 'sort --help' for more information.\n", err)
470			return 2
471		}
472		o := order{tab: noTab}
473		unique := false
474		// global is the key the global options describe: the whole line.
475		var global key
476		for _, g := range given {
477			switch g.Name {
478			case 'b':
479				global.skipStart, global.skipEnd = true, true
480			case 'f':
481				global.fold = true
482			case 'h':
483				global.human = true
484			case 'n':
485				global.numeric = true
486			case 'r':
487				global.reverse = true
488			case 's':
489				o.noLastResort = true
490			case 'u':
491				o.noLastResort, unique = true, true
492			case 'k':
493				k, err := parseKey(g.Value)
494				if err != nil {
495					fmt.Fprintf(stderr, "sort: %v\n", err)
496					return 2
497				}
498				o.keys = append(o.keys, k)
499			case 't':
500				tab, err := parseTab(g.Value)
501				if err == nil && o.tab != noTab && o.tab != tab {
502					err = errors.New("incompatible tabs")
503				}
504				if err != nil {
505					fmt.Fprintf(stderr, "sort: %v\n", err)
506					return 2
507				}
508				o.tab = tab
509			}
510		}
511		o.reverse = global.reverse
512		for i, k := range o.keys {
513			if k.plain() {
514				o.keys[i].skipStart, o.keys[i].skipEnd = global.skipStart, global.skipEnd
515				o.keys[i].numeric, o.keys[i].reverse = global.numeric, global.reverse
516				o.keys[i].fold, o.keys[i].human = global.fold, global.human
517			}
518		}
519		if len(o.keys) == 0 && (global.numeric || global.skipStart || global.fold || global.human) {
520			o.keys = []key{global}
521		}
522		// As in GNU, a key may sort by number or by size, not both; the
523		// options are named without b and r, which do not conflict.
524		for _, k := range o.keys {
525			if k.numeric && k.human {
526				opts := "hn"
527				if k.fold {
528					opts = "fhn"
529				}
530				fmt.Fprintf(stderr, "sort: options '-%s' are incompatible\n", opts)
531				return 2
532			}
533		}
534		// As GNU does, every input must open before any is read, and sort
535		// stops at the first that will not, or that opens but will not read,
536		// printing nothing.
537		if err := input.Check(names); err != nil {
538			fmt.Fprintf(stderr, "sort: cannot read: %s\n", input.Message(err))
539			return 2
540		}
541		srcs, err := input.Read(names, stdin)
542		if err != nil {
543			fmt.Fprintf(stderr, "sort: read failed: %s\n", input.Message(err))
544			return 2
545		}
546		var lines [][]byte
547		for _, s := range srcs {
548			lines = append(lines, input.Lines(s.Data)...)
549		}
550		// The sort is stable, so of lines that compare equal the first in the
551		// input comes first, and it is the one -u keeps, as in GNU.
552		slices.SortStableFunc(lines, o.compare)
553		for i, l := range lines {
554			if unique && i > 0 && o.compare(lines[i-1], l) == 0 {
555				continue
556			}
557			stdout.Write(append(l, '\n'))
558		}
559		return 0
560	}
561

