// Command sort prints the lines of its input in order, as GNU sort does in
// the C locale: by bytes, or by number with -n, reversed with -r, ignoring
// leading blanks with -b, folding lowercase to uppercase with -f, by
// human-readable sizes such as 2K and 1M with -h, and by the keys -k gives, in fields split by -t;
// -s keeps lines whose keys tie in input order and -u prints only the first
// of them.
package main

import (
	"bytes"
	"cmp"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"slices"
	"strings"

	"example.com/coreutils/internal/input"
	"example.com/coreutils/internal/opts"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

var spec = opts.Spec{
	Flags:  "bfhnrsu",
	Valued: "kt",
	Long: map[string]byte{
		"ignore-leading-blanks": 'b',
		"ignore-case":           'f',
		"human-numeric-sort":    'h',
		"numeric-sort":          'n',
		"reverse":               'r',
		"stable":                's',
		"unique":                'u',
		"key":                   'k',
		"field-separator":       't',
	},
}

// noTab is the field separator when -t is not given: fields are then
// separated by the empty string between a non-blank and a blank, so each
// field but the first starts with the blanks that precede it.
const noTab = -1

// unbounded stands for a field or character count too large to reach.
const unbounded = math.MaxInt

// key is one sort key, as -k gives it or as the global options make one of
// the whole line. Fields and characters count from zero here. A key with
// end false runs to the end of the line; an echar of zero ends the key at
// the end of field eword.
type key struct {
	sword, schar int
	eword, echar int
	end          bool
	// skipStart and skipEnd skip blanks before counting the start and
	// end characters, as b does in POS1 and POS2.
	skipStart, skipEnd bool
	numeric, reverse   bool
	// fold compares lowercase ASCII letters as uppercase, as f does.
	fold bool
	// human compares sizes such as 2K and 1M, as h does.
	human bool
}

// plain reports whether the key gives no ordering options of its own, in
// which case it takes the global ones, as GNU's keys do.
func (k key) plain() bool {
	return !k.skipStart && !k.skipEnd && !k.numeric && !k.reverse && !k.fold && !k.human
}

func blank(c byte) bool { return c == ' ' || c == '\t' }

// field returns the part of line the key covers, found as GNU's begfield
// and limfield find it.
func (k key) field(line []byte, tab int) []byte {
	lim := len(line)
	if k.end {
		lim = k.limit(line, tab)
	}
	beg := k.begin(line, tab)
	if beg >= lim {
		return nil
	}
	return line[beg:lim]
}

func (k key) begin(line []byte, tab int) int {
	p, n := 0, len(line)
	for w := k.sword; p < n && w > 0; w-- {
		p = skipField(line, p, tab)
		if tab != noTab && p < n {
			p++
		}
	}
	if k.skipStart {
		for p < n && blank(line[p]) {
			p++
		}
	}
	return advance(p, k.schar, n)
}

func (k key) limit(line []byte, tab int) int {
	p, n := 0, len(line)
	w := k.eword
	if k.echar == 0 && w < unbounded {
		w++ // the whole of the end field
	}
	for ; p < n && w > 0; w-- {
		p = skipField(line, p, tab)
		if tab != noTab && p < n && (w > 1 || k.echar != 0) {
			p++
		}
	}
	if k.echar != 0 {
		if k.skipEnd {
			for p < n && blank(line[p]) {
				p++
			}
		}
		p = advance(p, k.echar, n)
	}
	return p
}

// skipField moves from p past one field, up to its separator: with a tab,
// to the next tab; without, past leading blanks and then the non-blanks.
func skipField(line []byte, p, tab int) int {
	n := len(line)
	if tab != noTab {
		for p < n && int(line[p]) != tab {
			p++
		}
		return p
	}
	for p < n && blank(line[p]) {
		p++
	}
	for p < n && !blank(line[p]) {
		p++
	}
	return p
}

func advance(p, by, n int) int {
	if by >= n-p {
		return n
	}
	return p + by
}

// order is how lines compare: by their keys in turn, then, when every key
// ties, by their bytes, reversed by the global -r alone. With keys, -s and
// -u skip that last resort, so lines whose keys tie compare equal; without
// keys, the whole line is the key.
type order struct {
	keys    []key
	tab     int
	reverse bool
	// noLastResort is set by -s or -u.
	noLastResort bool
}

// unitOrder is the rank of a size's unit as -h reads it: 0 for none, then
// K (or k), M, G, T, P, E, Z, Y, R, Q from 1.
func unitOrder(c byte) int {
	if c == 'k' {
		c = 'K'
	}
	return strings.IndexByte("KMGTPEZYRQ", c) + 1
}

// humanOrder finds the unit of s's leading number, as GNU's
// find_unit_order does: the byte after its digits and any fraction, when
// some digit is not zero; negated for a negative number. No unit, or a
// number all zeros, ranks 0. With fold, as with -f, the unit is read
// uppercased, so 5g is 5G.
func humanOrder(s []byte, fold bool) int {
	i := 0
	for i < len(s) && blank(s[i]) {
		i++
	}
	neg := i < len(s) && s[i] == '-'
	if neg {
		i++
	}
	nonzero := false
	digits := func() {
		for ; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
			nonzero = nonzero || s[i] != '0'
		}
	}
	digits()
	if i < len(s) && s[i] == '.' {
		i++
		digits()
	}
	if !nonzero || i >= len(s) {
		return 0
	}
	u := s[i]
	if fold && 'a' <= u && u <= 'z' {
		u -= 'a' - 'A'
	}
	o := unitOrder(u)
	if neg {
		o = -o
	}
	return o
}

// humancompare compares two sizes as -h does: by unit, then by number as
// -n compares them.
func humancompare(a, b []byte, fold bool) int {
	if c := cmp.Compare(humanOrder(a, fold), humanOrder(b, fold)); c != 0 {
		return c
	}
	return numcompare(a, b)
}

// foldCompare compares a and b as bytes with lowercase ASCII letters made
// uppercase, as GNU's -f does in the C locale; so "_" sorts after letters.
func foldCompare(a, b []byte) int {
	for i := 0; i < len(a) && i < len(b); i++ {
		x, y := a[i], b[i]
		if 'a' <= x && x <= 'z' {
			x -= 'a' - 'A'
		}
		if 'a' <= y && y <= 'z' {
			y -= 'a' - 'A'
		}
		if x != y {
			return cmp.Compare(x, y)
		}
	}
	return cmp.Compare(len(a), len(b))
}

func (o order) compare(a, b []byte) int {
	for _, k := range o.keys {
		x, y := k.field(a, o.tab), k.field(b, o.tab)
		var c int
		if k.numeric {
			c = numcompare(x, y)
		} else if k.human {
			c = humancompare(x, y, k.fold)
		} else if k.fold {
			c = foldCompare(x, y)
		} else {
			c = bytes.Compare(x, y)
		}
		if c != 0 {
			if k.reverse {
				c = -c
			}
			return c
		}
	}
	if len(o.keys) > 0 && o.noLastResort {
		return 0
	}
	c := bytes.Compare(a, b)
	if o.reverse {
		c = -c
	}
	return c
}

// specError is a bad -k argument, in GNU's words.
func specError(msg, spec string) error {
	return fmt.Errorf("%s: invalid field specification %s", msg, input.QuoteAlways(spec))
}

// count reads a field or character count at the start of s, as GNU's
// parse_field_count does: optional white space and plus sign, then
// digits. A count too large to hold reads as unbounded.
func count(s, msg string) (int, string, error) {
	i := 0
	for i < len(s) && strings.IndexByte(" \t\n\v\f\r", s[i]) >= 0 {
		i++
	}
	if i < len(s) && s[i] == '+' {
		i++
	}
	start := i
	n := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		d := int(s[i] - '0')
		if n > (unbounded-d)/10 {
			n = unbounded
		} else if n != unbounded {
			n = n*10 + d
		}
		i++
	}
	if i == start {
		return 0, "", fmt.Errorf("%s: invalid count at start of %s", msg, input.QuoteAlways(s))
	}
	return n, s[i:], nil
}

// options reads the ordering letters after a position. b applies to the
// start or the end of the key, depending on which position it follows.
func options(s string, k *key, end bool) (string, error) {
	for ; s != ""; s = s[1:] {
		switch s[0] {
		case 'b':
			if end {
				k.skipEnd = true
			} else {
				k.skipStart = true
			}
		case 'n':
			k.numeric = true
		case 'r':
			k.reverse = true
		case 'f':
			k.fold = true
		case 'h':
			k.human = true
		case 'd', 'g', 'i', 'M', 'R', 'V':
			return "", fmt.Errorf("key option '%c' is not supported", s[0])
		default:
			return s, nil
		}
	}
	return s, nil
}

// parseKey reads a -k argument: POS1[,POS2], each position F[.C][OPTS].
func parseKey(spec string) (key, error) {
	var k key
	n, s, err := count(spec, "invalid number at field start")
	if err != nil {
		return k, err
	}
	if n == 0 {
		return k, specError("field number is zero", spec)
	}
	k.sword = n - 1
	if strings.HasPrefix(s, ".") {
		if n, s, err = count(s[1:], "invalid number after '.'"); err != nil {
			return k, err
		}
		if n == 0 {
			return k, specError("character offset is zero", spec)
		}
		k.schar = n - 1
	}
	if s, err = options(s, &k, false); err != nil {
		return k, err
	}
	if strings.HasPrefix(s, ",") {
		k.end = true
		if n, s, err = count(s[1:], "invalid number after ','"); err != nil {
			return k, err
		}
		if n == 0 {
			return k, specError("field number is zero", spec)
		}
		k.eword = n - 1
		if strings.HasPrefix(s, ".") {
			if k.echar, s, err = count(s[1:], "invalid number after '.'"); err != nil {
				return k, err
			}
		}
		if s, err = options(s, &k, true); err != nil {
			return k, err
		}
	}
	if s != "" {
		return k, specError("stray character in field spec", spec)
	}
	return k, nil
}

// parseTab reads a -t argument: one byte, or "\0" for the NUL byte.
func parseTab(s string) (int, error) {
	switch {
	case s == "":
		return 0, errors.New("empty tab")
	case s == `\0`:
		return 0, nil
	case len(s) > 1:
		return 0, fmt.Errorf("multi-character tab %s", input.QuoteAlways(s))
	}
	return int(s[0]), nil
}

// number is a line's leading number, as -n reads it: its sign, its
// integer digits without leading zeros and its fraction digits without
// trailing zeros.
type number struct {
	neg      bool
	whole    []byte
	fraction []byte
}

// parseNumber reads a line's leading number: blanks, an optional minus,
// digits, and an optional point with more digits. A line that does not
// start with one reads as zero, and so does negative zero.
func parseNumber(s []byte) number {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
		i++
	}
	var n number
	if i < len(s) && s[i] == '-' {
		n.neg = true
		i++
	}
	start := i
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	n.whole = bytes.TrimLeft(s[start:i], "0")
	if i < len(s) && s[i] == '.' {
		i++
		start = i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		n.fraction = bytes.TrimRight(s[start:i], "0")
	}
	if len(n.whole) == 0 && len(n.fraction) == 0 {
		n.neg = false
	}
	return n
}

// numcompare compares the leading numbers of two lines exactly, digit by
// digit, however long they are.
func numcompare(a, b []byte) int {
	x, y := parseNumber(a), parseNumber(b)
	if x.neg != y.neg {
		if x.neg {
			return -1
		}
		return 1
	}
	c := magnitude(x, y)
	if x.neg {
		c = -c
	}
	return c
}

func magnitude(x, y number) int {
	if len(x.whole) != len(y.whole) {
		if len(x.whole) < len(y.whole) {
			return -1
		}
		return 1
	}
	if c := bytes.Compare(x.whole, y.whole); c != 0 {
		return c
	}
	return bytes.Compare(x.fraction, y.fraction)
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	given, names, err := opts.Parse(args, spec)
	if err != nil {
		fmt.Fprintf(stderr, "sort: %v\nTry 'sort --help' for more information.\n", err)
		return 2
	}
	o := order{tab: noTab}
	unique := false
	// global is the key the global options describe: the whole line.
	var global key
	for _, g := range given {
		switch g.Name {
		case 'b':
			global.skipStart, global.skipEnd = true, true
		case 'f':
			global.fold = true
		case 'h':
			global.human = true
		case 'n':
			global.numeric = true
		case 'r':
			global.reverse = true
		case 's':
			o.noLastResort = true
		case 'u':
			o.noLastResort, unique = true, true
		case 'k':
			k, err := parseKey(g.Value)
			if err != nil {
				fmt.Fprintf(stderr, "sort: %v\n", err)
				return 2
			}
			o.keys = append(o.keys, k)
		case 't':
			tab, err := parseTab(g.Value)
			if err == nil && o.tab != noTab && o.tab != tab {
				err = errors.New("incompatible tabs")
			}
			if err != nil {
				fmt.Fprintf(stderr, "sort: %v\n", err)
				return 2
			}
			o.tab = tab
		}
	}
	o.reverse = global.reverse
	for i, k := range o.keys {
		if k.plain() {
			o.keys[i].skipStart, o.keys[i].skipEnd = global.skipStart, global.skipEnd
			o.keys[i].numeric, o.keys[i].reverse = global.numeric, global.reverse
			o.keys[i].fold, o.keys[i].human = global.fold, global.human
		}
	}
	if len(o.keys) == 0 && (global.numeric || global.skipStart || global.fold || global.human) {
		o.keys = []key{global}
	}
	// As in GNU, a key may sort by number or by size, not both; the
	// options are named without b and r, which do not conflict.
	for _, k := range o.keys {
		if k.numeric && k.human {
			opts := "hn"
			if k.fold {
				opts = "fhn"
			}
			fmt.Fprintf(stderr, "sort: options '-%s' are incompatible\n", opts)
			return 2
		}
	}
	// As GNU does, every input must open before any is read, and sort
	// stops at the first that will not, or that opens but will not read,
	// printing nothing.
	if err := input.Check(names); err != nil {
		fmt.Fprintf(stderr, "sort: cannot read: %s\n", input.Message(err))
		return 2
	}
	srcs, err := input.Read(names, stdin)
	if err != nil {
		fmt.Fprintf(stderr, "sort: read failed: %s\n", input.Message(err))
		return 2
	}
	var lines [][]byte
	for _, s := range srcs {
		lines = append(lines, input.Lines(s.Data)...)
	}
	// The sort is stable, so of lines that compare equal the first in the
	// input comes first, and it is the one -u keeps, as in GNU.
	slices.SortStableFunc(lines, o.compare)
	for i, l := range lines {
		if unique && i > 0 && o.compare(lines[i-1], l) == 0 {
			continue
		}
		stdout.Write(append(l, '\n'))
	}
	return 0
}

