// Package input reads what the tools read: standard input when no file is
// named, else each named file in turn, "-" naming standard input, split
// into lines.
package input

import (
	"bytes"
	"errors"
	"io"
	"os"
	"strings"
)

// Source is one input a tool reads: its name as given on the command line,
// empty for standard input, and its bytes.
type Source struct {
	Name string
	Data []byte
	// Regular reports whether the input is a regular file, whose size is
	// known before it is read.
	Regular bool
	Size    int64
	// Opened reports whether the input was opened, even if it could not
	// then be read.
	Opened bool
}

// Read reads the inputs a tool was given: standard input when names is
// empty, else each named input in order, "-" naming standard input. It
// stops at the first input it cannot read and returns the sources read so
// far with the error.
func Read(names []string, stdin io.Reader) ([]Source, error) {
	if len(names) == 0 {
		src, err := ReadStdin(stdin)
		if err != nil {
			return nil, err
		}
		return []Source{src}, nil
	}
	var out []Source
	for _, name := range names {
		src, err := ReadName(name, stdin)
		if err != nil {
			return out, err
		}
		out = append(out, src)
	}
	return out, nil
}

// ReadName reads one named input: standard input, named "-", when name is
// "-", else the file.
func ReadName(name string, stdin io.Reader) (Source, error) {
	if name == "-" {
		src, err := ReadStdin(stdin)
		src.Name = name
		return src, err
	}
	return ReadFile(name)
}

// ReadStdin reads standard input, unnamed. When it is an open file, such
// as a regular file redirected in, its size is known as a named file's is.
// Reading it again, as for a second "-", finds it already at its end.
func ReadStdin(stdin io.Reader) (Source, error) {
	var src Source
	if f, ok := stdin.(*os.File); ok {
		if fi, err := f.Stat(); err == nil && fi.Mode().IsRegular() {
			src.Regular, src.Size = true, fi.Size()
		}
	}
	src.Opened = true
	data, err := io.ReadAll(stdin)
	src.Data = data
	return src, err
}

// ReadFile reads one named file. When the file opens but cannot be read,
// as a directory cannot, the source it returns with the error is Opened,
// with the file's name and kind but no data.
func ReadFile(name string) (Source, error) {
	f, err := os.Open(name)
	if err != nil {
		return Source{}, err
	}
	defer f.Close()
	src := Source{Name: name, Opened: true}
	if fi, err := f.Stat(); err == nil && fi.Mode().IsRegular() {
		src.Regular, src.Size = true, fi.Size()
	}
	data, err := io.ReadAll(f)
	if err != nil {
		return src, &os.PathError{Op: "read", Path: name, Err: err}
	}
	src.Data = data
	return src, nil
}

// Message describes an error reading an input as GNU does: the input's
// name, quoted as a shell would need it, then the system's description of
// the error, capitalized.
func Message(err error) string {
	var pe *os.PathError
	if errors.As(err, &pe) {
		return Quote(pe.Path) + ": " + Reason(err)
	}
	return err.Error()
}

// Reason is the system's description of an error reading an input,
// capitalized as GNU prints it, without the input's name.
func Reason(err error) string {
	for {
		var pe *os.PathError
		if !errors.As(err, &pe) {
			break
		}
		err = pe.Err
	}
	msg := err.Error()
	if msg != "" {
		msg = strings.ToUpper(msg[:1]) + msg[1:]
	}
	return msg
}

// Check opens each named file and closes it again, returning the first
// error, as GNU sort does to make sure it can read every input before it
// sorts any. Standard input, "-", needs no check.
func Check(names []string) error {
	for _, name := range names {
		if name == "-" {
			continue
		}
		f, err := os.Open(name)
		if err != nil {
			return err
		}
		f.Close()
	}
	return nil
}

// Lines splits data into its lines, each without its newline. A final
// line that lacks a newline is still a line; an empty input has none.
func Lines(data []byte) [][]byte {
	if len(data) == 0 {
		return nil
	}
	data = bytes.TrimSuffix(data, []byte{'\n'})
	return bytes.Split(data, []byte{'\n'})
}

