// Command uniq prints its input with each run of adjacent identical lines
// written once, as GNU uniq does in the C locale; -c prefixes each with the
// run's length, -d prints only the runs of more than one line and -u only
// the lines that stand alone, -i compares lines ignoring ASCII case, and
// -f and -s skip leading fields and bytes before comparing.
package main

import (
	"bytes"
	"fmt"
	"io"
	"math"
	"os"
	"strconv"
	"strings"

	"example.com/coreutils/internal/input"
	"example.com/coreutils/internal/opts"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

var spec = opts.Spec{
	Flags:  "cdiu",
	Valued: "fs",
	Long: map[string]byte{
		"count":       'c',
		"repeated":    'd',
		"ignore-case": 'i',
		"unique":      'u',
		"skip-fields": 'f',
		"skip-chars":  's',
	},
}

// skip is what -f and -s skip before lines compare: fields, each blanks
// then non-blanks, then bytes.
type skip struct{ fields, chars int }

func blank(c byte) bool { return c == ' ' || c == '\t' }

// rest is the part of line that compares, as GNU's find_field finds it.
func (k skip) rest(line []byte) []byte {
	i := 0
	for f := 0; f < k.fields && i < len(line); f++ {
		for i < len(line) && blank(line[i]) {
			i++
		}
		for i < len(line) && !blank(line[i]) {
			i++
		}
	}
	return line[i+min(k.chars, len(line)-i):]
}

// count reads a -f or -s argument as GNU does: optional white space and
// plus sign, then digits; a number too large to hold reads as unbounded.
// Anything else, any minus sign included, is an error.
func count(s, what string) (int, error) {
	t := strings.TrimLeft(s, " \t\n\v\f\r")
	t = strings.TrimPrefix(t, "+")
	if t == "" || strings.Trim(t, "0123456789") != "" {
		return 0, fmt.Errorf("%s: invalid number of %s to skip", s, what)
	}
