import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"example.com/coreutils/internal/input"
	"example.com/coreutils/internal/opts"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

var spec = opts.Spec{
	Flags: "lwmcL",
	Long: map[string]byte{
		"lines":           'l',
		"words":           'w',
		"chars":           'm',
		"bytes":           'c',
		"max-line-length": 'L',
	},
}

// counts are what wc counts in one input. In the C locale chars are
// bytes. maxLine is the widest line's width, as -L measures it.
type counts struct {
	lines, words, chars, bytes, maxLine int
}

// add adds c to a total: the counts sum, but the widest line is the
// widest of either.
func (t *counts) add(c counts) {
	t.lines += c.lines
	t.words += c.words
	t.chars += c.chars
	t.bytes += c.bytes
	t.maxLine = max(t.maxLine, c.maxLine)
}

// which counts to print, in the fixed order lines, words, chars, bytes,
// longest line.
type which struct {
	lines, words, chars, bytes, maxLine bool
}

func (w which) n() int {
	n := 0
	for _, b := range []bool{w.lines, w.words, w.chars, w.bytes, w.maxLine} {
		if b {
			n++
		}
	}
	return n
}

// selection reads which counts the options ask for: those named, or all
// three when none is.
func selection(given []opts.Opt) which {
	var w which
	for _, o := range given {
		switch o.Name {
		case 'l':
			w.lines = true
		case 'w':
			w.words = true
		case 'm':
			w.chars = true
		case 'c':
			w.bytes = true
		case 'L':
			w.maxLine = true
		}
	}
	if w.n() == 0 {
		w = which{lines: true, words: true, bytes: true}
	}
	return w
}

// count counts data's newlines, words, chars and bytes, and measures its
// widest line. A word is a run of bytes that holds at least one printable
// byte, delimited by white space; a byte that is neither printable nor
// white space neither starts nor ends one. A line's width, as GNU measures
// it in the C locale, counts each printable byte and space as one and
// takes a tab to the next multiple of eight; other bytes have no width,
// and a carriage return or form feed starts the width again.
func count(data []byte) counts {
	c := counts{chars: len(data), bytes: len(data)}
	inWord := false
	pos := 0
	for _, b := range data {
		switch b {
		case '\n', '\r', '\f':
			if b == '\n' {
				c.lines++
			}
			c.maxLine = max(c.maxLine, pos)
			pos = 0
		case '\t':
			pos += 8 - pos%8
		case ' ':
			pos++
		}
		switch {
		case b == ' ' || b == '\t' || b == '\v' || b == '\f' || b == '\r' || b == '\n':
			inWord = false
		case b >= 0x21 && b <= 0x7e:
			pos++
			if !inWord {
				c.words++
				inWord = true
			}
		}
	}
	c.maxLine = max(c.maxLine, pos)
	return c
}

// width is the width every count is right-aligned to: one when a single
// count of a single input is printed; seven when an input is not a regular
// file; else the digits of the inputs' total size. Inputs counts every
// input given, srcs only those opened.
func width(w which, inputs int, srcs []input.Source) int {
	if w.n() == 1 && inputs == 1 {
		return 1
	}
	min := 1
	var total int64
	for _, s := range srcs {
		if s.Regular {
			total += s.Size
		} else {
			min = 7
		}
	}
	n := len(strconv.FormatInt(total, 10))
	if n < min {
		n = min
	}
	return n
}

// line formats one input's counts: the selected counts in the order
// lines, words, chars, bytes, longest line, each right-aligned to the width and separated by a
// space, then the input's name when it has one.
func line(c counts, w which, wid int, name string) string {
	var parts []string
	for _, f := range []struct {
		on bool
		n  int
	}{{w.lines, c.lines}, {w.words, c.words}, {w.chars, c.chars}, {w.bytes, c.bytes}, {w.maxLine, c.maxLine}} {
		if f.on {
			parts = append(parts, fmt.Sprintf("%*d", wid, f.n))
		}
	}
	if name != "" {
		parts = append(parts, name)
	}
	return strings.Join(parts, " ") + "\n"
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	given, names, err := opts.Parse(args, spec)
	if err != nil {
		fmt.Fprintf(stderr, "wc: %v\nTry 'wc --help' for more information.\n", err)
		return 1
	}
	w := selection(given)
	if len(names) == 0 {
		src, err := input.ReadStdin(stdin)
		if err != nil {
			fmt.Fprintf(stderr, "wc: %v\n", err)
			return 1
		}
		io.WriteString(stdout, line(count(src.Data), w, width(w, 1, []input.Source{src}), ""))
		return 0
	}
	// Every input is read before any is printed, since the width depends
	// on them all. One that cannot be read is reported in its turn and the
	// rest are still counted, as GNU does; one that opened but could not
	// be read, as a directory, still prints its zero counts.
	srcs := make([]input.Source, len(names))
	errs := make([]error, len(names))
	var opened []input.Source
	for i, name := range names {
		srcs[i], errs[i] = input.ReadName(name, stdin)
		if srcs[i].Opened {
			opened = append(opened, srcs[i])
		}
	}
	wid := width(w, len(names), opened)
	code := 0
	var total counts
	for i, s := range srcs {
		if errs[i] != nil {
			fmt.Fprintf(stderr, "wc: %s\n", input.Message(errs[i]))
			code = 1
		}
		if !s.Opened {
			continue
		}
		c := count(s.Data)
		total.add(c)
		io.WriteString(stdout, line(c, w, wid, s.Name))
	}
	if len(names) > 1 {
		io.WriteString(stdout, line(total, w, wid, "total"))
	}
	return code
}

