}

// The long-only options' names.
const (
	complementOpt      = 0x01
	outputDelimiterOpt = 0x02
)

var spec = opts.Spec{
	Flags:    "s\x01",
	Valued:   "bcdf\x02",
	LongOnly: "\x01\x02",
	Long: map[string]byte{
		"bytes":            'b',
