// -M, numbered from one and separated by commas or blanks.
func parseList(s string, w words) (list, error) {
	var l list
	var value uint64
	initial := uint64(1)
	dash, lhs, rhs := false, false, false
	numStart := -1
	for i := 0; ; i++ {
		var c byte
		if i < len(s) {
			c = s[i]
