					l = append(l, span{clamp(initial), clamp(value)})
				}
			} else {
				if value == 0 {
					return nil, errors.New(w.zero)
				}
				l = append(l, span{clamp(value), clamp(value)})
			}
			value = 0
			if i == len(s) {
				return l, nil
			}
			lhs, rhs = false, false
		case c >= '0' && c <= '9':
			if numStart < 0 {
				numStart = i
			}
			if dash {
				rhs = true
			} else {
				lhs = true
			}
			d := uint64(c - '0')
			if value > (math.MaxUint64-d)/10 || value*10+d == math.MaxUint64 {
				end := numStart
				for end < len(s) && s[end] >= '0' && s[end] <= '9' {
					end++
				}
				return nil, fmt.Errorf(w.tooLarge, s[numStart:end])
			}
			value = value*10 + d
		default:
			return nil, fmt.Errorf(w.invalid, s[i:])
		}
