// does; spans that only touch, as 1-2,3-4, stay apart, so an output
// delimiter still falls between them. With complement, the list becomes
// the spans between and around them.
func normalize(l list, complement bool) list {
	slices.SortFunc(l, func(a, b span) int { return cmp.Compare(a.lo, b.lo) })
	var merged list
	for _, sp := range l {
		if n := len(merged); n > 0 && sp.lo <= merged[n-1].hi {
			merged[n-1].hi = max(merged[n-1].hi, sp.hi)
			continue
		}
		merged = append(merged, sp)
	}
	if !complement {
		return merged
	}
	var out list
	if merged[0].lo > 1 {
		out = append(out, span{1, merged[0].lo - 1})
	}
	for i := 1; i < len(merged); i++ {
		if merged[i-1].hi+1 != merged[i].lo {
