// that the normalized list's spans select. In the C locale a character is
// a byte, so -c cuts the same.
func positions(line []byte, outDelim []byte, l list) []byte {
	var out [][]byte
	for _, sp := range l {
		if sp.lo > len(line) {
			break
		}
