		switch o.Name {
		case 'd':
			if len(o.Value) != 1 {
				return nil, errors.New("the delimiter must be a single character")
			}
			delim, delimGiven = o.Value[0], true
		case 'b', 'c', 'f':
			if mode != 0 {
				return nil, errors.New("only one list may be specified")
			}
			mode, spec = o.Name, o.Value
		case complementOpt:
			complement = true
		case 's':
			onlyDelimited = true
		case outputDelimiterOpt:
			// As in GNU, an empty output delimiter is the NUL byte.
