		return nil, errors.New("you must specify a list of bytes, characters, or fields")
	}
	if delimGiven && mode != 'f' {
		return nil, errors.New("an input delimiter may be specified only when operating on fields")
	}
	if onlyDelimited && mode != 'f' {
		return nil, errors.New("suppressing non-delimited lines makes sense\n\tonly when operating on fields")
	}
	if mode == 'f' {
		l, err := parseList(spec, fieldWords)
		if err != nil {
			return nil, err
		}
		l = normalize(l, complement)
		if outDelim == nil {
			outDelim = []byte{delim}
		}
		return func(line []byte) ([]byte, bool) { return fields(line, delim, outDelim, l, onlyDelimited) }, nil
	}
	l, err := parseList(spec, positionWords)
	if err != nil {
		return nil, err
	}
	l = normalize(l, complement)
	return func(line []byte) ([]byte, bool) { return positions(line, outDelim, l), true }, nil
