func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	given, names, err := opts.Parse(args, spec)
	if err == nil {
		var cutter func([]byte) ([]byte, bool)
		if cutter, err = config(given); err == nil {
			// An input that cannot be read is reported in its turn and
			// the rest are still cut, as GNU does.
			if len(names) == 0 {
				names = []string{"-"}
			}
			code := 0
			for _, name := range names {
				src, err := input.ReadName(name, stdin)
				if err != nil {
					fmt.Fprintf(stderr, "cut: %s\n", input.Message(err))
